// Generated from server/.env.example by scripts/sync-env-template.mjs. Do not edit by hand.
export const ENV_EXAMPLE = "# server/.env — secrets and per-deployment settings ONLY.\n#\n# Static portal URLs (login pages, portal endpoints) are NOT here: they are the\n# same for every deployment, so they live as defaults in app/config.py and are\n# the single source of truth. Put only secrets and things that legitimately\n# change per environment below.\n#\n# QUOTING — wrap any password containing punctuation in SINGLE quotes:\n#\n#     UNISON_PASSWORD='pa$$w0rd%#with^symbols'\n#\n# Single quotes are the safest form every reader of this file agrees on, as\n# measured against python-dotenv 1.2.2 and `source .env` in bash:\n#\n#   in the value      unquoted              \"double\"              'single'\n#   ---------------------------------------------------------------------------\n#   ` #` (after a     TRUNCATED — the       safe                  safe\n#   space)            rest is a comment\n#   $NAME             safe in dotenv,       safe in dotenv,       safe\n#                     EXPANDED by a shell   EXPANDED by a shell\n#   ${NAME}           EXPANDED              EXPANDED              EXPANDED\n#   backslash         safe in dotenv,       MANGLED — \\b, \\t etc  safe\n#                     eaten by a shell      are read as escapes\n#\n# So: use single quotes. The one case no quoting can save is a literal `${` —\n# python-dotenv expands it whatever the quoting, so a password containing `${`\n# has to be passed as a real environment variable instead of through this file.\n# A single quote itself also cannot appear inside single quotes.\n#\n# app/core/credentials.py checks all of this at run start: it re-reads the raw\n# line and compares it against what the app loaded, so a mangled credential is\n# reported as a mangled credential rather than as a portal login failure.\n\n# -- Portal credentials ------------------------------------------------------\n# MyFloridaMarketPlace runs as one of two vendor logins, chosen per run in the\n# console — two clients, two registrations, the same catalogue of ads. An\n# account with either key blank is shown as unavailable in the picker and cannot\n# be started, so a run never reaches the one-time password challenge with\n# credentials that were never going to work.\n#\n# ACC1 is the Hoope Lab account, ACC2 is Auston Lucas. The keys keep their\n# positional names because they are what is already deployed — renaming a key\n# that holds a working credential buys nothing. The console shows the client's\n# name, not the key.\nMYFLORIDA_ACC1_USERNAME=your_hoope_lab_username\nMYFLORIDA_ACC1_PASSWORD=your_hoope_lab_password\nMYFLORIDA_ACC2_USERNAME=your_auston_lucas_username\nMYFLORIDA_ACC2_PASSWORD=your_auston_lucas_password\n\n# The keys from before there was a choice. Hoope Lab falls back to these when\n# MYFLORIDA_ACC1_* are unset, so an existing deployment keeps working untouched;\n# set the pair above instead for anything new.\nMFMP_EMAIL=your_email_here\nMFMP_PASSWORD=your_password_here\n\n# RideMetro (Bonfire) runs as one of two accounts, chosen per run in the\n# console. They are separate logins into separate Euna Supplier Networks, so the\n# choice decides which agencies a run sweeps. An account with either key blank\n# is shown as unavailable in the picker and cannot be started.\nHOOPE_LAB_USERNAME=your_email_here\nHOOPE_LAB_PASSWORD=your_password_here\n\nFEDPOINT_USERNAME=your_email_here\nFEDPOINT_PASSWORD=your_password_here\n\n# Superseded by HOOPE_LAB_* above, and still read as that account's credentials\n# when they are set and HOOPE_LAB_* are not. Leave blank on a new deployment.\n# EUNA_BONFIRE_EMAIL=\n# EUNA_BONFIRE_PASSWORD=\n\n# Windows app sign-in: the account panel on Vercel (admin/ in this repo). Both travel\n# in the credentials file; leave blank for development, where nobody signs in.\n# The key must equal HUB_API_KEY in the Vercel project's environment variables.\nSCRAPING_HUB_ACCOUNTS_URL=\nSCRAPING_HUB_API_KEY=\n\n# COMMBUYS (Massachusetts, https://www.commbuys.com) — the supplier login used to\n# sign in before the Advanced search for Bid Solicitations.\nCOMMBUYS_USERNAME=your_user_id_here\nCOMMBUYS_PASSWORD=your_password_here\n\nBIDNET_USERNAME=your_email_here\nBIDNET_PASSWORD=your_password_here\n\nNORTHDAKOTA_USERNAME=your_username_here\nNORTHDAKOTA_PASSWORD=your_password_here\n# Manual-login mode: force a visible browser and wait for a human to solve the\n# B2C reCAPTCHA. Requires a desktop/display where someone is present.\nNORTHDAKOTA_MANUAL_LOGIN=true\nNORTHDAKOTA_MANUAL_LOGIN_TIMEOUT=300\n\nSEPTA_USERNAME=your_username_here\nSEPTA_PASSWORD=your_password_here\n\n# City of Philadelphia (PHLContracts) — the Open Bids list is behind a vendor\n# login, so a run needs an account on the portal.\nPHILA_EMAIL=your_email_here\nPHILA_PASSWORD=your_password_here\n\n# EMMA (eMaryland Marketplace Advantage) — Public Solicitations is behind a\n# supplier login. Plain email/password form; no SSO or CAPTCHA.\nEMMA_USERNAME=your_email_here\nEMMA_PASSWORD=your_password_here\n\n# OpenGov Procurement — vendor login (email, then password). Network ->\n# Current Opportunities is behind it.\nOPENGOV_EMAIL=\nOPENGOV_PASSWORD=\n\nCal_ePROCURE_USERNAME=your_username_here\nCal_ePROCURE_PASSWORD=your_password_here\n\n# Unison Marketplace credentials (SAM.gov and NAICS need no credentials;\n# Wisconsin is a public portal with no login).\nUNISON_EMAIL=your_email@example.com\n# Single-quoted: this account's password carries $ / % / # / ^ (see QUOTING above).\nUNISON_PASSWORD='your_password'\n\n# -- Post-scrape email / S3 notifications ------------------------------------\n# On a successful run the archive ZIP (cumulative Excel + documents) is emailed\n# through the mail server below, with the download link in the body and an\n# optional S3 upload. Leave RECIPIENT_EMAILS blank to disable notifications entirely.\nRECIPIENT_EMAILS=email1@example.com,email2@example.com\nAWS_S3_BUCKET_NAME=your_s3_bucket_name\nAWS_ACCESS_KEY_ID=your_aws_access_key_id\nAWS_SECRET_ACCESS_KEY=your_aws_secret_access_key\nAWS_REGION=us-east-1\n\n# -- Mail server --------------------------------------------------------------\n# Gmail (free, about 500 emails a day). Needs 2-Step Verification on the Google\n# account, then Google Account -> Security -> App passwords -> create one, and\n# paste its 16 letters below (spaces are fine). Not the normal Gmail password.\nSMTP_HOST=smtp.gmail.com\nSMTP_PORT=587\nSMTP_USERNAME=yourname@gmail.com\nSMTP_PASSWORD=your_16_letter_app_password\nSMTP_FROM=Scraping Hub <yourname@gmail.com>\n# Used only when SMTP_HOST is blank: Amazon SES's SMTP interface.\nAWS_SES_FROM_EMAIL=no-reply@yourdomain.com\nAWS_SES_USERNAME=your_ses_smtp_username\nAWS_SES_PASSWORD=your_ses_smtp_password\n\n# -- Sign-in alerts ---------------------------------------------------------\n# Every sign-in to the Windows app emails these addresses (comma-separated):\n# who, when, public IP, PC name, Windows user, local IP, app version, and how the\n# sign-in was checked. Uses the mail server above. Blank = no alerts.\nSIGNIN_ALERT_EMAILS=admin@yourdomain.com\n\n# Base URL recipients can reach this server at — used to build the download\n# link in the notification email. This is deployment-specific (localhost in dev,\n# your public domain/tunnel in production), which is why it belongs here.\nPUBLIC_BASE_URL=http://localhost:9001\n\n# -- Storage & runtime (optional — sensible defaults in app/config.py) --------\n# SCRAPE_CONCURRENCY  how many scrapes run at once; the rest queue (default 3).\n#                     Each run drives its own Chrome at ~300-500 MB, so this is\n#                     a memory budget more than a speed dial. Raise on a bigger box.\n# WORK_DIR   scratch workspace for in-flight runs (default: system temp dir)\n# ARCHIVE_DIR where finished-run ZIPs are stored (default: ../data/archives)\n# WORK_DIR=\n# ARCHIVE_DIR=../data/archives\n\n# -- Database ----------------------------------------------------------------\nDATABASE_URL=postgresql+psycopg2://USER:PASSWORD@localhost:5432/scraping-hub\n";
